// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output `generated`, whether decoding is
// currently inside a math-computation span, and the active constrained span
// contents `currentConstrainedOut`. Outside spans it generates freely, but it
// also watches for arithmetic cue tokens such as "=" so that the next action
// can explicitly open a `<< >>` span for a computation. Inside spans it keeps
// the parser as the hard authority and uses an adaptive constrained step with a
// mild repetition penalty against already-generated tokens, which encourages
// short arithmetic expressions while preserving validity.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained free-generation branch, we either stay
//   outside the span or observe `next == "<<"`, in which case we enter with
//   `currentConstrainedOut := []`, valid by the method precondition
//   `parser.IsValidPrefix([])`. In the explicit-open branch, OpenConstrainedSpan
//   likewise returns an empty constrained prefix, so validity holds. In the
//   close branch, CloseConstrainedSpan sets `insideConstrainedOut` to false,
//   making the implication vacuous. In the active constrained branch, both
//   AdaptiveConstrainedStepWithPenalties and ConstrainedStep return either EOS
//   or a parser-valid next token; after excluding EOS, AppendConstrainedToken
//   preserves `parser.IsValidPrefix(currentConstrainedOut)`.
// progress: In the free-generation branch, UnconstrainedStep consumes one token
//   step and appends at most one visible token, so `|generated| <=
//   |generatedPrefix| + steps` is preserved after `steps := steps + 1`. In the
//   explicit-open and close branches, OpenConstrainedSpan and CloseConstrainedSpan
//   each consume one step and append at most one delimiter token, so the same
//   bound is preserved. In the active constrained branch, each constrained-step
//   helper consumes one token step; EOS may consume budget without visible
//   growth, and non-EOS tokens are appended once via AppendConstrainedToken, so
//   visible growth is still at most the consumed budget.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var openArmed: bool := false;
var narrowThreshold: nat := 12;
var penaltyTokens: seq<Token> := [">>", "<<"];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if openArmed {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      openArmed := false;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := enteredGenerated;
          insideConstrainedOut := enteredInside;
          currentConstrainedOut := enteredCurrent;
          openArmed := false;
        } else if next == "=" || next == ":" {
          openArmed := true;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var nextConstrained := eosToken;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if validCount <= narrowThreshold {
      nextConstrained := helpers.AdaptiveConstrainedStepWithPenalties(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, penaltyTokens, 4.0, narrowThreshold, eosToken
      );
    } else {
      nextConstrained := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
    }

    steps := steps + 1;
    if nextConstrained == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, nextConstrained
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;
